package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.time.LocalDate;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class LendingIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    }

    @Test
    void loaning_a_sixth_book_while_holding_five_returns_409() throws Exception {
        String memberId = registerMember("박지훈");
        for (int i = 1; i <= 5; i++) {
            mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                            .content(objectMapper.writeValueAsString(new LoanBody(registerBook("책 " + i), memberId))))
                    .andExpect(status().isCreated());
        }

        String sixthBookId = registerBook("책 6");
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new LoanBody(sixthBookId, memberId))))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("LOAN_LIMIT_EXCEEDED"));

        mockMvc.perform(get("/books/{id}", sixthBookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("AVAILABLE"));
    }

    @Test

    @Test
    void searching_books_treats_like_wildcards_literally() throws Exception {
        String token = UUID.randomUUID().toString().replace("-", "");
        registerBook("100% Pure " + token);
        registerBook("100 Pure " + token);

        mockMvc.perform(get("/books").param("title", "100% pure " + token))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].title").value("100% Pure " + token));
    }

    @Test
    void searching_books_without_title_returns_400() throws Exception {
        mockMvc.perform(get("/books")).andExpect(status().isBadRequest());
        mockMvc.perform(get("/books").param("title", " ")).andExpect(status().isBadRequest());
    }

    @Test
    void discarding_an_available_book_marks_it_discarded() throws Exception {
        String bookId = registerBook("훼손된 책");

        mockMvc.perform(post("/books/{id}/discard", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.id").value(bookId))
                .andExpect(jsonPath("$.title").value("훼손된 책"))
                .andExpect(jsonPath("$.status").value("DISCARDED"));

        mockMvc.perform(get("/books/{id}", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("DISCARDED"));
    }

    @Test
    void loaning_a_discarded_book_returns_409() throws Exception {
        String bookId = registerBook("분실된 책");
        mockMvc.perform(post("/books/{id}/discard", bookId)).andExpect(status().isOk());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new LoanBody(bookId, registerMember("윤지호")))))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_DISCARDED"));
    }

    @Test
    void discarding_a_book_on_loan_returns_409_and_keeps_it_on_loan() throws Exception {
        String bookId = registerBook("대출 중인 책");
        String loanId = loanBook(bookId, registerMember("한도윤"));

        mockMvc.perform(post("/books/{id}/discard", bookId))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_ON_LOAN"));

        mockMvc.perform(get("/books/{id}", bookId))
                .andExpect(jsonPath("$.status").value("ON_LOAN"));

        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isOk());
        mockMvc.perform(post("/books/{id}/discard", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("DISCARDED"));
    }

    @Test
    void discarding_an_already_discarded_book_keeps_it_discarded() throws Exception {
        String bookId = registerBook("두 번 폐기되는 책");
        mockMvc.perform(post("/books/{id}/discard", bookId)).andExpect(status().isOk());

        mockMvc.perform(post("/books/{id}/discard", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("DISCARDED"));
    }

    @Test
    void discarding_an_unknown_book_returns_404() throws Exception {
        mockMvc.perform(post("/books/{id}/discard", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    private void assertLateFee(String returnedAt, int overdueDays, int lateFee) throws Exception {
        String loanId = loanBookOn(registerBook("연체 " + returnedAt), registerMember("송민재"), "2026-01-01");

        mockMvc.perform(post("/loans/{loanId}/return", loanId).contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"" + returnedAt + "\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanId").value(loanId))
                .andExpect(jsonPath("$.returnedAt").value(returnedAt))
                .andExpect(jsonPath("$.overdueDays").value(overdueDays))
                .andExpect(jsonPath("$.lateFee").value(lateFee));
    }

    private String loanBookOn(String bookId, String memberId, String loanedAt) throws Exception {
        String response = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new DatedLoanBody(bookId, memberId, loanedAt))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("loanId").asText();
    }

    private String loanBook(String bookId, String memberId) throws Exception {
        String response = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new LoanBody(bookId, memberId))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("loanId").asText();
    }

    private String registerBook(String title) throws Exception {
        String response = mockMvc.perform(post("/books").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new TitleBody(title))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("id").asText();
    }

    private String registerMember(String name) throws Exception {
        String response = mockMvc.perform(post("/members").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new NameBody(name))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("memberId").asText();
    }

    record TitleBody(String title) {
    }

    record NameBody(String name) {
    }

    record LoanBody(String bookId, String memberId) {
    }

    record DatedLoanBody(String bookId, String memberId, String loanedAt) {
    }
}

